const $=id=>document.getElementById(id);const fields=['mode','duration','ratio','idea','style','definitions','summary','retention','sound','music','silent','noMusic'];let shots=[{time:0,description:'A symmetrical mandala fills the center of the frame. Its concentric rings rotate slowly clockwise while geometric petals expand outward and settle back into their original arrangement. The camera holds a static shot.',dialogue:'',speaker:'',language:'Japanese',voiceover:false}];
function state(){return Object.fromEntries(fields.map(k=>[k,$(k).type==='checkbox'?$(k).checked:$(k).value]).concat([['shots',shots],['schemaVersion',1],['translations',typeof userTranslations==='undefined'?{}:userTranslations]]))}
function timestamp(t){let ms=Math.round(t*1000);return String(Math.floor(ms/60000)).padStart(2,'0')+':'+(String(Math.floor(ms/1000)%60).padStart(2,'0'))+'.'+String(ms%1000).padStart(3,'0')}
function compose(s){const dur=Number(s.duration),n=s.shots.length;let prefix='';if(s.mode==='I2VA')prefix='For the target video, at 0.00 seconds into the target video, <Picture 1> (from [Shot 1]) is fully referenced.\n\n';if(s.mode==='FL2VA')prefix=`How the reference pictures align with the target video — Picture 1 (from Shot 1) aligns with the 0.00-second mark of the target video; Picture 2 (from Shot ${n}) aligns with the ${dur.toFixed(2)}-second mark of the target video.\n\n`;if(s.mode==='L2VA')prefix=`How the reference pictures align with the target video — <Picture 1> (from [Shot ${n}]) aligns with the ${dur.toFixed(2)}-second mark of the target video.\n\n`;
let body=s.shots.map((x,i)=>{let line=`[Shot ${i+1}] ${i?`At ${timestamp(Number(x.time))}, the camera cuts to `:''}${i===0&&s.mode!=='Ref2VA'?s.style.trim()+' ':''}${x.description.trim()}`;if(x.dialogue){line+=` ${x.speaker.trim()} ${x.voiceover?'says in an off-screen voiceover':'says'}: <d>[${x.language}] ${x.dialogue}</d>${x.voiceover?' while their lips remain completely closed.':''}`}return line}).join('\n');if(s.mode==='Ref2VA')body=s.style.trim()+'\n'+body;let sound=s.silent?'N/A':s.sound.trim(),music=s.silent||s.noMusic?'N/A':s.music.trim();return s.mode==='Ref2VA'?`subject_definitions:\n${s.definitions.trim()}\n\nsummary:\n${s.summary.trim()}\n\nretention_analysis:\n${s.retention.trim()}\n\ndetailed_description:\n${body}\n\noverall_soundscape:\n${sound}\n\nnon_diegetic_music:\n${music}`:prefix+`integrated_multimodal_description: ${body}\n\noverall_soundscape: ${sound}\n\nnon_diegetic_music: ${music}`}
function validate(s){let w=[],d=Number(s.duration);if(!Number.isFinite(d)||d<4||d>15)w.push('長さは4〜15秒にしてください。');let prev=0;s.shots.forEach((x,i)=>{if(!x.description.trim())w.push(`Shot ${i+1}の映像説明が空です。`);if(i&&(!Number.isFinite(Number(x.time))||Number(x.time)<=prev||Number(x.time)>=d))w.push(`Shot ${i+1}のカット時刻は直前より後、動画の終わりより前にしてください。`);prev=Number(x.time);if(x.dialogue&&!/\(S[1-9]\d*(?:,S[1-9]\d*)*\)/.test(x.speaker))w.push(`Shot ${i+1}の話者に固定ID（例：The man (S1)）が必要です。`);if(x.dialogue&&/<\/?d>|<scenetrans>|<cutoff>/.test(x.dialogue))w.push('特殊なセリフ継続・打切りタグは完成プロンプトを手動で確認してください。');});if(s.silent&&s.shots.some(x=>x.dialogue))w.push('完全無音とセリフが両方指定されています。');if(!s.silent&&!s.sound.trim())w.push('環境音を入力してください。完全な無音はチェックで指定します。');if(!s.silent&&!s.noMusic&&!s.music.trim())w.push('BGMを入力するか、BGMなしを選んでください。');let english=[s.style,s.sound,s.music,...s.shots.map(x=>x.description)];if(s.mode==='Ref2VA'){english.push(s.definitions,s.summary,s.retention);if(!s.definitions.trim()||!s.summary.trim()||!s.retention.trim())w.push('参照モードの定義・要約・保持分析をすべて入力してください。');if(!/^\[[^\]]+\]/.test(s.summary.trim()))w.push('summaryを[reference generation]等のタスク種別で始めてください。');const defs=new Set((s.definitions.match(/<(?:Subject|Picture|Video|Audio) \d+>/g)||[]));const used=(s.summary+s.retention+s.shots.map(x=>x.description+x.speaker).join(' ')+s.sound+s.music).match(/<(?:Subject|Picture|Video|Audio) \d+>/g)||[];for(let label of new Set(used))if(!defs.has(label))w.push(`${label}の定義がありません。`);if(!s.retention.match(/fully_preserved|partially_preserved|attribute_transfer|weak_reference|fully_copy|partially_copy|reference/))w.push('retention_analysisに公式の保持関係マーカーを指定してください。');}if(english.some(x=>/[ぁ-んァ-ヶ一-龠]/.test(x)))w.push('本文に日本語が含まれています。セリフ・画面内文字以外は英語化してください。');if(s.mode==='FL2VA'&&s.shots.length>1)w.push('先頭＋末尾画像は通常1ショットが推奨です。複数ショットが意図した指定か確認してください。');if(['I2VA','FL2VA','L2VA'].includes(s.mode))w.push('画像の内容と開始・終了への連続した動きを説明し、生成先へ画像を渡してください。');if(s.mode==='Ref2VA'&&s.shots.map(x=>x.description).join(' ').split(/\s+/).length<350)w.push('参照生成の詳細説明は通常350〜500英単語が目安です。具体的な情報を補ってください。');return [...new Set(w)]}
function update(){let s=state();$('refs').hidden=s.mode!=='Ref2VA';$('modeHelp').textContent={T2VA:'文章だけで映像と音の流れを作ります。',I2VA:'Picture 1を先頭フレームとして、そこからの動きを説明します。',FL2VA:'Picture 1からPicture 2へ、途切れない変化を説明します。',L2VA:'最終ショットでPicture 1の状態へ到達する動きを説明します。',Ref2VA:'素材・役割・保持関係を定義。画像は9枚まで、動画と音声は各3本まで、合計12ファイルまで。動画・音声は各2〜15秒、種別ごとの合計15秒まで。音声だけの入力は不可。'}[s.mode];$('output').value=compose(s);let w=validate(s);$('checks').replaceChildren();let el=document.createElement('div');el.className=w.length?'warning':'ok';el.textContent=w.length?'確認事項：\n'+w.join('\n'):'形式チェックOK。意味・参照素材の一致・セリフが収まる長さは生成前に確認してください。';el.style.whiteSpace='pre-line';$('checks').append(el);if(typeof syncBilingual==='function')syncBilingual()}
function render(){let box=$('shots');box.replaceChildren();shots.forEach((x,i)=>{let div=document.createElement('div');div.className='shot';div.innerHTML='<div class="row"><strong></strong><button type="button">削除</button></div>';div.querySelector('strong').textContent=`Shot ${i+1}`;div.querySelector('button').disabled=shots.length===1;div.querySelector('button').onclick=()=>{shots.splice(i,1);shots[0].time=0;render();update()};function control(key,label,type){let l=document.createElement('label');l.textContent=label;let inp=document.createElement(type==='textarea'?'textarea':'input');if(type!=='textarea')inp.type=type;inp.value=x[key]??'';if(type==='checkbox')inp.checked=x[key];if(type==='number'){inp.min='0';inp.step='0.001'}inp.oninput=()=>{x[key]=type==='checkbox'?inp.checked:inp.value;update()};l.append(inp);div.append(l)}if(i)control('time','カット時刻（秒）','number');control('description','構図・主役・動き・カメラ・その場の音（英語）','textarea');control('speaker','話者（英語＋固定ID。例：The elderly man with a low voice (S1)）','text');control('dialogue','セリフ（原文をそのまま保持）','textarea');control('language','セリフの言語名（Japanese / English等）','text');control('voiceover','画面外のナレーション','checkbox');box.append(div)})}
fields.forEach(k=>$(k).addEventListener('input',update));$('add').onclick=()=>{shots.push({time:Number($('duration').value)*shots.length/(shots.length+1),description:'',speaker:'',dialogue:'',language:'Japanese',voiceover:false});render();update()};function notice(t){$('status').textContent=t}async function copy(id){try{await navigator.clipboard.writeText($(id).value);notice('コピーしました。')}catch{ $(id).focus();$(id).select();notice('コピーできませんでした。選択された文章を手動でコピーしてください。')}}$('copy').onclick=()=>copy('output');$('copyAI').onclick=()=>copy('aiOutput');function download(name,text,mime){let url=URL.createObjectURL(new Blob([text],{type:mime}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('txt').onclick=()=>download('h3-prompt.txt',$('output').value,'text/plain;charset=utf-8');$('json').onclick=()=>download('h3-draft.json',JSON.stringify(state(),null,2),'application/json');$('save').onclick=()=>{try{localStorage.setItem('h3-draft-v1',JSON.stringify(state()));notice('このブラウザに下書きを保存しました。')}catch{notice('保存できませんでした。JSON保存を使ってください。')}};
function load(s){if(s.schemaVersion!==1||!['T2VA','I2VA','FL2VA','L2VA','Ref2VA'].includes(s.mode)||!Array.isArray(s.shots)||!s.shots.length||s.shots.length>50)throw Error('形式');for(let k of fields){if(['silent','noMusic'].includes(k)){if(typeof s[k]!=='boolean')throw Error('形式')}else if(typeof s[k]!=='string')throw Error('形式')}for(let x of s.shots){for(let k of ['description','speaker','dialogue','language'])if(typeof x[k]!=='string')throw Error('形式');if(!Number.isFinite(Number(x.time))||typeof x.voiceover!=='boolean')throw Error('形式')}fields.forEach(k=>$(k).type==='checkbox'?$(k).checked=s[k]:$(k).value=s[k]);shots=s.shots;if(typeof userTranslations!=='undefined'&&s.translations&&typeof s.translations==='object'&&!Array.isArray(s.translations)){for(const [en,ja] of Object.entries(s.translations))if(typeof ja==='string')userTranslations[en]=ja}render();update()}
$('import').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>1000000)throw Error('size');load(JSON.parse(await f.text()));notice('下書きを読み込みました。')}catch{notice('読み込めませんでした。このツールで保存した1MB以下のJSONを選んでください。')}e.target.value=''};
for(const [key,p] of Object.entries(sampleCatalog)){let o=document.createElement('option');o.value=key;o.textContent=p.title;$('preset').append(o)}
function applySample(){let p=nextSample($('preset').value);$('mode').value='T2VA';$('style').value=p.style;$('sound').value=p.sound;$('music').value=p.music;$('idea').value='';$('noMusic').checked=p.music==='N/A';$('silent').checked=false;shots=[{time:0,description:p.description,speaker:'',dialogue:'',language:'Japanese',voiceover:false}];render();update();notice(p.title+' / バリエーション '+p.variant+' を作成しました。')}
$('example').onclick=applySample;$('preset').onchange=applySample;
$('ai').onclick=()=>{let s=state();$('aiOutput').value=`MiniMax H3公式のプロンプト作成ガイドに従い、以下の入力を生成用プロンプトへ書き換えてください。素材が見えない場合は内容を推測せず、必要な説明を質問してください。\n公式ガイド：https://github.com/MiniMax-AI/MiniMax-H3/tree/main/skills/h3-prompt-writing\nモード：${s.mode}、長さ：${s.duration}秒、比率：${s.ratio}\n日本語の案：${s.idea||'下記の下書きを改善してください。'}\n\n規則：本文は英語。セリフ・歌詞・画面内文字は原文を保持。通常モードはintegrated_multimodal_description、overall_soundscape、non_diegetic_musicの順。Ref2VAはsubject_definitions、summary、retention_analysis、detailed_description、overall_soundscape、non_diegetic_musicの順。Ref2VAの詳細は通常350〜500英単語を目安。ラベルの役割を定義して一貫させる。保持関係は公式マーカーを使う。summaryはタスク種別を[]で先頭に記載。\n[Shot 1]には時刻を付けず、後続は[Shot N] At MM:SS.mmm, the camera cuts to ...。カットは単調増加し動画長より前。カメラの動きは自然な英文で種類・振幅・速度を記述。話者は固定(S1)等、セリフは<d>[Japanese] 原文</d>。ナレーションはsays in an off-screen voiceoverと記述し、直後に画面内人物の唇が閉じていることを記述。環境音は1〜4文、BGMは楽器・テンポ・変化を1〜3文で。完全無音時の環境音およびBGMなしはN/A。キーフレームの先頭指示は下記下書きの正確な表記を保持し、開始と終了の間に具体的な変化を記述。\n\n入力下書き（空欄は未指定）：\n${compose(s)}\n\n完成プロンプトを英語で出力し、その後に別枠で日本語訳を併記してください。セリフは原文を保持してください。`; $('aiPanel').open=true;notice('AI書き換え依頼文を作りました。コピーしてAIへ渡してください。')};
try{let saved=localStorage.getItem('h3-draft-v1');if(saved)load(JSON.parse(saved));else{render();update()}}catch{render();update()}
if(typeof module!=='undefined')module.exports={compose,validate,timestamp};
